//! Weapon and gadget names from the embedded `data/weapons.json` table.
//!
//! Keys are game item IDs (the `weaponItemId` the patched r6-dissect reads from the killer's
//! operator loadout block), not the raw asset ID of the kill packet (`weaponId`). The table is
//! generated by `tools/gen-weapons` from wnc-replay/replay-tool `analysis/names.go` (MIT).
//! Unknown IDs give `None`; nothing is guessed.

use serde::Deserialize;
use std::collections::HashMap;
use std::sync::OnceLock;

const WEAPONS_JSON: &str = include_str!("../../../data/weapons.json");

#[derive(Deserialize)]
struct Entry {
    name: String,
    #[serde(default)]
    kind: String,
}

struct Weapon {
    name: String,
    kind: String,
}

fn table() -> &'static HashMap<u64, Weapon> {
    static T: OnceLock<HashMap<u64, Weapon>> = OnceLock::new();
    T.get_or_init(|| match serde_json::from_str::<HashMap<String, Entry>>(WEAPONS_JSON) {
        Ok(m) => m
            .into_iter()
            .filter_map(|(id, e)| {
                let id = id.parse::<u64>().ok()?;
                Some((id, Weapon { name: e.name, kind: e.kind }))
            })
            .collect(),
        Err(e) => {
            log::error!("embedded weapon table is invalid: {e}");
            HashMap::new()
        }
    })
}

/// Display name for a game item ID, e.g. `R4-C`.
pub fn weapon_name(id: u64) -> Option<&'static str> {
    table().get(&id).map(|w| w.name.as_str())
}

/// Item kind from the source table: `weapon`, `ability`, `gadget`, `reinforcement`, `drone`,
/// `objective`, `equipment` or `other`.
pub fn weapon_kind(id: u64) -> Option<&'static str> {
    table().get(&id).map(|w| w.kind.as_str()).filter(|k| !k.is_empty())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_loads() {
        assert!(table().len() > 500, "weapon table has {} entries", table().len());
    }

    #[test]
    fn known_ids_resolve() {
        assert_eq!(weapon_name(0x37802D177E), Some("R4-C"));
        assert_eq!(weapon_kind(0x37802D177E), Some("weapon"));
        assert_eq!(weapon_name(0x37802D1C53), Some("416-C CARBINE"));
    }

    #[test]
    fn unknown_ids_are_none() {
        assert_eq!(weapon_name(0), None);
        assert_eq!(weapon_name(1366019316), None); // a raw kill asset ID, not a game item ID
        assert_eq!(weapon_kind(1), None);
    }
}
